import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第四十三章 如来修行不是为了获得好处","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/43第四十三章 如来修行不是为了获得好处.md","filePath":"meditation/巴利文大藏经/43第四十三章 如来修行不是为了获得好处.md"}'),o={name:"meditation/巴利文大藏经/43第四十三章 如来修行不是为了获得好处.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第四十三章-如来修行不是为了获得好处" tabindex="-1">第四十三章 如来修行不是为了获得好处 <a class="header-anchor" href="#第四十三章-如来修行不是为了获得好处" aria-label="Permalink to &quot;第四十三章 如来修行不是为了获得好处&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部7相应18经/打柴者经(婆罗门相应/有偈篇/祇夜)</p><p>有个时候，佛陀住在骄萨罗国的某处森林中，那个时候，有个姓婆罗堕若的婆罗门，他让他的众多弟子们，到森林中砍柴，他们进入森林的深处，看见佛陀在一棵大树下盘腿静坐，一动不动，感到非常的吃惊，于是他们就立刻转身回去见他们的老师，他们对老师说：“尊师，我们今天到人迹罕至的密林中砍柴，看见有个出家人在一棵大树下盘腿打坐，您需不需要去看看，我们感到很吃惊，所以就回来告诉您。”</p><p>那个时候，婆罗堕若姓的婆罗门就与他的弟子们一同前往密林的深处，他们沿着之前做好的标记，很快就再次来到佛陀打坐的地方。那个姓婆罗堕若的婆罗门，看见佛陀盘腿静坐，一动不动，于是就走进佛陀，他对佛陀说：“出家人，你独自一人，进入深山老林不害怕吗？这里到处都是危险哦，这里有老虎、豺狼等等猛兽出没，还有毒蛇、毒虫等等毒物到处爬行，你一个人在这里打坐不害怕吗？</p><p>你在这里盘腿打坐，一动不动，既然不害怕猛兽和毒物前来加害你，你的内心没有生出恐怖和害怕的心，实在是很难得，你内心不被外界的环境影响而变化，真的是非常的不错，你静坐在这里，自己不唱歌，也很难听到别人唱歌，也没有美妙的音乐供你娱乐，你自己不说话，也很难听到别人说话，没有人为你排解寂寞。你独自一人在人迹罕至的深山老林里面修行，让我们感到非常的不可思议，你能够长时间的这样独自居住在如此危险寂静的密林之中，我想你是想通过这样的修行上生到梵天界吧，你想与创造世界的大梵天王在一起吧。</p><p>大德，你到底是为了什么在这个人迹罕至的深山老林里面苦修的呢？难道真是为了上生到梵天界里，与创世主大梵天王在一起吗？”</p><p>这时，婆罗门说偈言：</p><p>「深森有多怖，独入于空林。</p><p>心不动实美，甚美之比丘。</p><p>汝是在禅思，无能在此歌。</p><p>亦无能言语，独圣者依林。</p><p>心喜独住林，我见实希有。</p><p>我思念乃此，愿生于无上。</p><p>三天世界主，为作同伴者。</p><p>何故独于林，尊者修苦行。</p><p>为达于梵否。」</p><p>佛陀说：“世间的凡夫，会有贪爱和执着，他们会期待和欢喜生到不同层级的天界之中，他们修行的目的是为了获得回报和好处，他们想通过苦行来上生到梵天界，与创世主大梵天王在一起，他们内心生起这些贪求的欲望，都是没有智慧的表现。</p><p>这些贪求如来早就在内心中全部都断除了，如来没有任何的期待，没有任何的贪爱和执着，既不期待欢喜生到不同层级的天界之中，也不会想通过修行获得回报和好处。</p><p>如来修行既不是为了上生到梵天界，与大梵天王在一起，也不是为了满足各种欲望。</p><p>如来已经没有任何的期待，不为功德，不为除灭罪业，不为生天界，不为获得回报和好处。</p><p>如来没有贪念和欲望，也不会接近这些会让内心生起贪念和欲望的事物事情，这些都是世间的束缚和捆绑，如来不挂念和执着世间一切的事物事情，内心已经没有任何的欲望、期待、挂念、执着。</p><p>当然也不会被世间一切的事物事情所束缚和捆绑。</p><p>如来已经从一切的烦恼和痛苦中解脱出来，内心清净无染。</p><p>如来已经证悟了无上正等正觉的佛果，已经证悟达到了无上解脱的境界。婆罗门如来在人迹罕至的密林中独自的修行，内心没有生起或挂念喜怒哀乐等等一切的念想。既然没有生起或挂念一切的念想，那么刚才你说的这些恐怖和害怕的念想也没有在内心中生起或挂念，如来就是这样在密林中静坐修行的。”</p><p>这时，佛陀说偈言：</p><p>「凡夫种种著，爱欲或欢喜。</p><p>生自无知根，一切我断除。</p><p>我无贪无欲，亦不与接近。</p><p>有诸清净见，到达于无上。</p><p>吉祥之正觉，婆罗门我独。</p><p>于无畏禅思。」</p><p>佛陀说法后，那个姓婆罗堕若的婆罗门，立刻和他的弟子们跪在地上顶礼佛陀，他们异口同声的对佛陀说：“圣者，感谢您对我们说法，您说的法，我们从来都没有听到过，您说的法让我们在黑暗中看见了光明，圣者，请您让我们皈依您，让我们做您的在家修行弟子吧，我们愿意终身都受持您制定的戒律，我们愿意终身都按您的正法去修行。”</p><p>佛陀接受了婆罗门和他弟子们的皈依。</p>',34)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
